use lindera::mode::Mode;
use lindera::segmenter::Segmenter; let dictionary = load_dictionary("embedded://ipadic")?;
let segmenter = Segmenter::new(Mode::Normal, dictionary, None); Segmenter::new does not check a user dictionary against the system dictionary. Segmenter::try_new takes the same arguments and returns an error when an entry's context ID lies outside the system dictionary's connection matrix; Segmenter::new accepts such an entry, and segmentation then panics when the entry matches the input (see Context IDs ). Building from a configuration checks too. load_user_dictionary_for loads a user dictionary for a loaded system dictionary and checks a .csv already as it builds it, so the error names the row's CSV line and surface; try_new names an entry of a .bin, or of a user dictionary loaded with load_user_dictionary and metadata only, by its word id. use lindera::dictionary::{load_dictionary, load_user_dictionary_for};
use lindera::mode::Mode;
use lindera::segmenter::Segmenter; let dictionary = load_dictionary("embedded://ipadic")?;
